(349, 21, 1, 'Hasil dari 3/4 + 2/5 adalah...', NULL, '23/20', '45905', '45689', '44136', NULL, 'A', 'KPK 4 dan 5 = 20. 3/4 = 15/20, 2/5 = 8/20. Jadi 15/20 + 8/20 = 23/20', 1, '2025-09-23 08:14:11', '2025-09-23 08:14:11'),
(350, 21, 2, 'Bentuk desimal dari pecahan 7/8 adalah...', NULL, '0,875', '0,785', '0,857', '0,758', NULL, 'A', '7 ÷ 8 = 0,875 (pembagian langsung)', 1, '2025-09-23 08:14:11', '2025-09-23 08:14:11'),
(351, 21, 3, 'Hasil dari 2,5 × 0,8 adalah...', NULL, '2,0', '1,8', '2,4', '3,3', NULL, 'A', '2,5 × 0,8 = 25/10 × 8/10 = 200/100 = 2,0', 1, '2025-09-23 08:14:11', '2025-09-23 08:14:11'),
(352, 21, 4, 'Rasio umur Ani dan Budi adalah 3:4. Jika umur Ani 15 tahun, maka umur Budi adalah...', NULL, '20 tahun', '18 tahun', '12 tahun', '25 tahun', NULL, 'A', 'Ani : Budi = 3 : 4. Jika Ani 15, maka 15/3 = 5. Umur Budi = 4 × 5 = 20 tahun', 1, '2025-09-23 08:14:11', '2025-09-23 08:14:11'),
(353, 21, 5, 'Bentuk persen dari 0,35 adalah...', NULL, '0.35', '3,5%', '3.5', '0,35%', NULL, 'A', 'Untuk mengubah desimal ke persen, kalikan dengan 100. 0,35 × 100 = 35%', 1, '2025-09-23 08:14:11', '2025-09-23 08:14:11'),
(354, 21, 6, 'Hasil dari 5/6 - 1/3 adalah...', NULL, '45689', '45720', '45718', '45812', NULL, 'A', '5/6 - 1/3 = 5/6 - 2/6 = 3/6 = 1/2', 1, '2025-09-23 08:14:11', '2025-09-23 08:14:11'),
(355, 21, 7, 'Dalam kelas terdapat 24 siswa dengan rasio siswa laki-laki dan perempuan 5:3. Jumlah siswa laki-laki adalah...', NULL, '15 siswa', '9 siswa', '12 siswa', '18 siswa', NULL, 'A', 'Total bagian = 5 + 3 = 8. Siswa laki-laki = (5/8) × 24 = 15 siswa', 1, '2025-09-23 08:14:11', '2025-09-23 08:14:11'),
(356, 21, 8, 'Hasil dari 1,25 + 2,75 - 0,5 adalah...', NULL, '3,5', '4,0', '3,0', '4,5', NULL, 'A', '1,25 + 2,75 = 4,00. Kemudian 4,00 - 0,5 = 3,5', 1, '2025-09-23 08:14:11', '2025-09-23 08:14:11'),
(357, 21, 9, 'Jika 2/3 dari suatu bilangan adalah 18, maka bilangan tersebut adalah...', NULL, '27', '12', '24', '36', NULL, 'A', 'Misalkan bilangan = x. Maka 2/3 × x = 18, sehingga x = 18 × 3/2 = 27', 1, '2025-09-23 08:14:11', '2025-09-23 08:14:11'),
